import { Manrope, Work_Sans, Kalam } from "next/font/google";
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap-icons/font/bootstrap-icons.css';
import "slick-carousel/slick/slick.css";
import "./assets/main.css";
import Header1 from "./Components/Header/Header1";
import Footer1 from "./Components/Footer/Footer1";
import WhatsAppFAB from "./Components/Common/WhatsAppFAB";
// import "./assets/custom.css"; // Add this line to import our custom styles

const manrope = Manrope({
  subsets: ['latin'],
  weight: ['400', '500', '600', '700', '800'],
  variable: '--body-color-font',
});

const work_sans = Work_Sans({
  subsets: ['latin'],
  weight: ['400', '500', '600', '700', '800'],
  variable: '--body-color-font',
});

const kalam = Kalam({
  subsets: ['latin'],
  weight: ['400', '700'],
  variable: '--heading-font',
});

export const metadata = {
  title: {
    absolute: '',
    default: 'M-RTours - Travel & Tour Agency NextJS Template',
    template: '%s | M-RTours - Travel & Tour Agency NextJS Template',
  },
  description: 'M-RTours - Travel & Tour Agency NextJS Template',
  openGraph: {
    title: 'M-RTours - Travel & Tour Agency NextJS Template',
    description: 'M-RTours - Travel & Tour Agency NextJS Template',
  },
};

export default function RootLayout({ children }) {
  return (
    <html lang="en">
      <head>
        <meta name="author" content="Themeservices" />
        <link rel="icon" href="/favicon.ico" sizes="any" />
      </head>
      <body className={`${manrope.variable} ${work_sans.variable} ${kalam.variable}`}>
        <div className='main-page-area3'>
          <Header1 />
          {children}
          <Footer1 />
        </div>
        {/* Global Floating WhatsApp Chat Button */}
        <WhatsAppFAB />
      </body>
    </html>
  );
}
